    "phases": [
      {
        "gates": [
          {
            "check": "Execute the legacy-compatibility acceptance suite and compare the recorded completion time with the approved migration start plus 14 calendar days.",
            "expected": "All legacy cases pass and recorded completion is no later than day 14.",
            "gate_id": "G-D-MIGRATION"
          },
          {
            "check": "Inspect the cutover roster and page both the primary and alternate cleanup and recovery owners during a rehearsal.",
            "expected": "Named primary and alternate owners acknowledge the page before cutover approval.",
            "gate_id": "G-OWNERS"
          },
          {
            "check": "Run a staged rollback drill from D while retaining the pre-D state, then rerun the legacy-compatibility acceptance suite.",
            "expected": "The prior state is restored and every legacy case passes.",
            "gate_id": "G-ROLLBACK"
          },
          {
            "check": "Run a timed D recovery drill led by the assigned recovery owner and record restoration and validation results.",
            "expected": "Recovery completes within the approved recovery objective and restored state passes validation; the objective must be approved before execution.",
            "gate_id": "G-D-RECOVERY"
          }
        ],
        "option": "D",
        "owner": "Migration Lead",
        "phase": 1,
        "purpose": "Provide the required legacy-compatible bridge within 14 days while preserving the pre-D state for rollback.",
        "rollback_triggers": [
          {
            "action": "Halt D expansion, retain the current legacy state, and escalate the migration plan for correction.",
            "check": "Review the dated migration milestone report each day.",
            "condition": "Any milestone projects legacy-compatible completion later than day 14.",
            "trigger_id": "RT-D-DEADLINE"
          },
          {
            "action": "Stop cutover and restore the preserved pre-D state.",
            "check": "Run G-D-RECOVERY and verify owner acknowledgement.",
            "condition": "No recovery owner acknowledges or any recovery drill fails its approved objective or state validation.",
            "trigger_id": "RT-D-RECOVERY"
          }
        ]
      },
      {
        "gates": [
          {
            "check": "Enumerate B mount targets and credential scopes in an isolated acceptance run and compare them with the approved workspace and least-privilege allowlists.",
            "expected": "Every mount is workspace-only and every credential is scoped to the approved task; no unexpected target or scope exists.",
            "gate_id": "G-B-ISOLATION"
          },
          {
            "check": "Repeat the owner-page rehearsal immediately before B cutover.",
            "expected": "Named primary and alternate cleanup and recovery owners acknowledge before cutover.",
            "gate_id": "G-B-OWNERS"
          },
          {
            "check": "Run a staged B-to-D rollback drill while retaining the validated D state, then rerun B isolation and legacy-compatibility checks on the restored D state.",
            "expected": "D state is restored, legacy cases pass, and B credentials are revoked.",
            "gate_id": "G-B-ROLLBACK"
          }
        ],
        "option": "B",
        "owner": "Execution Fabric Operations Lead",
        "phase": 2,
        "purpose": "Cut over from D to B as the isolation-supported target only after security, ownership, recovery, and rollback evidence is executable and passing.",
        "rollback_triggers": [
          {
            "action": "Block or reverse B cutover, revoke B credentials, and restore the preserved D state.",
            "check": "Continuously compare observed mount targets and credential scopes with the approved allowlists.",
            "condition": "Any mount escapes the workspace or any credential exceeds its approved task scope.",
            "trigger_id": "RT-B-ISOLATION"
          },
          {
            "action": "Stop B expansion and restore the preserved D state under the assigned recovery owner.",
            "check": "Run the recovery drill at cutover and after any provider or state-format change.",
            "condition": "The recovery owner is unavailable or restoration misses the approved recovery objective or fails state validation.",
            "trigger_id": "RT-B-RECOVERY"
          }
        ]
      }
    ],
    "strategy": "Stage D as the legacy-compatible bridge, then cut over to B only after ownership, rollback, recovery, and isolation gates pass; A remains a bounded warm-workload optimization and C is rejected."
